void Player::addSciencePurchasePoints(Int delta)
{
	if (delta > 0)
		m_scoreKeeper.rva0039B668(delta);
	Int oldSPP = getSciencePurchasePoints();
	SciencePurchasePointTracker::addSciencePurchasePoints(delta);
	if (oldSPP != getSciencePurchasePoints() && TheControlBar != NULL)
		TheControlBar->onPlayerRankChanged(this);
}

// FUNCTION: BFME2 0x002A9FA0 size=108 name=?rva002A9FA0@Rva002A9FA0@@QAE_NH@Z evidence=?:placeholder tier=A
Bool Player::setRankLevel(Int rankLevel)
{
	Int oldSPP = getSciencePurchasePoints();
	Bool changed = SciencePurchasePointTracker::setRankLevel(rankLevel);
	if (changed && TheControlBar != NULL)
	{
		if (this == ThePlayerList->getLocalPlayer() && TheEva != NULL)
			TheEva->reportEvaEvent((EvaEventID)2, NULL, NULL);
		TheControlBar->onPlayerRankChanged(this);
		if (oldSPP != getSciencePurchasePoints())
			TheControlBar->onPlayerRankChanged(this);
	}
	return changed;
}

