void Player::deleteUpgradeList()
{
	Upgrade *next;
	while (m_upgradeList)
	{
		next = m_upgradeList->getNext();
		::delete m_upgradeList;
		m_upgradeList = next;
	}
	memset(&m_upgradesInProgress, 0, 0x80);
	memset(&m_upgradesCompleted, 0, 0x80);
}

