// FUNCTION: BFME2 0x002AA91F size=163 name=?addRadar@Player@@QAEX_N@Z evidence=N:ledger tier=A
void Player::addRadar(Bool disableProof)
{
	Bool hadRadar = hasRadar();
	++m_radarCount;
	if (disableProof)
		++m_disableProofRadarCount;
	if (!hadRadar && hasRadar() && okToPlayRadarEdgeSound())
	{
		AudioEventRTS soundToPlay(TheAudio->getMiscAudio()->m_radarOnlineSound, 0);
		soundToPlay.setPlayerIndex(m_playerIndex);
		TheAudio->addAudioEvent(&soundToPlay);
	}
}

// FUNCTION: BFME2 0x002AA9C2 size=163 name=?removeRadar@Player@@QAEX_N@Z evidence=N:ledger tier=A
void Player::removeRadar(Bool disableProof)
{
	Bool hadRadar = hasRadar();
	--m_radarCount;
	if (disableProof)
		--m_disableProofRadarCount;
	if (hadRadar && !hasRadar() && okToPlayRadarEdgeSound())
	{
		AudioEventRTS soundToPlay(TheAudio->getMiscAudio()->m_radarOfflineSound, 0);
		soundToPlay.setPlayerIndex(m_playerIndex);
		TheAudio->addAudioEvent(&soundToPlay);
	}
}

