// FUNCTION: BFME2 0x002ABA3D size=94 name=?setUnitsVisionSpied@Player@@QAEX_NH@Z evidence=N:ledger tier=A
// Command & Conquer Generals' text (Zero Hour moved vision spying onto the units).
void Player::setUnitsVisionSpied(bool setting, int byWhom)
{
	Bool needRefresh = FALSE;

	if (setting)
	{
		m_visionSpiedBy[byWhom] = m_visionSpiedBy[byWhom] + 1;
		if (m_visionSpiedBy[byWhom] == 1)
			needRefresh = TRUE;
	}
	else
	{
		m_visionSpiedBy[byWhom] = m_visionSpiedBy[byWhom] - 1;
		if (m_visionSpiedBy[byWhom] == 0)
			needRefresh = TRUE;
	}

	if (needRefresh)
	{
		UnsignedInt workingMask = 0;
		for (Int i = 0; i < 20; ++i)
		{
			if (m_visionSpiedBy[i] > 0)
				workingMask |= (1 << i);
			else
				workingMask &= ~(1 << i);
		}

		m_visionSpiedMask = workingMask;

		iterateObjects(callHandleShroud, NULL);
	}
}

