// FUNCTION: BFME2 0x002ABE24 size=98 name=?allowedToBuild@Player@@QBE_NPBVThingTemplate@@@Z evidence=N:ledger tier=A
bool Player::allowedToBuild(const ThingTemplate *tmpl) const
{
	// a player barred from base or unit building may still build the other kind
	if (!m_canBuildBase && tmpl->isKindOf(KINDOF_STRUCTURE))
		return false;
	if (!m_canBuildUnits && !tmpl->isKindOf(KINDOF_STRUCTURE))
		return false;
	UnsignedShort templateID = tmpl->getTemplateID();
	return _STL::find(m_forbiddenTemplateIDs.begin(), m_forbiddenTemplateIDs.end(), templateID) == m_forbiddenTemplateIDs.end();
}

// FUNCTION: BFME2 0x002ABE86 size=67 name=?isCapableOfPurchasingScience@Player@@QBE_NW4ScienceType@@@Z evidence=N:ledger tier=A
Bool Player::isCapableOfPurchasingScience(ScienceType sci) const
{
	if (sci == SCIENCE_INVALID || hasScience(sci))
		return false;
	if (!hasPrereqsForScience(sci))
		return false;
	Int price = TheScienceStore->getSciencePurchaseCost(sci);
	if (price == 0 || price > getSciencePurchasePoints())
		return false;
	return true;
}

// FUNCTION: BFME2 0x002ABEC9 size=40 name=?getScienceAvailabilityTypeFromString@Player@@QAE?AW4ScienceAvailabilityType@@ABVAsciiString@@@Z evidence=N:ledger tier=A
ScienceAvailabilityType Player::getScienceAvailabilityTypeFromString(const AsciiString &name)
{
	for (Int i = 0; i < SCIENCE_AVAILABILITY_COUNT; ++i)
	{
		if (name.compareNoCase(ScienceAvailabilityNames[i]) == 0)
			return (ScienceAvailabilityType)i;
	}
	return SCIENCE_AVAILABILITY_INVALID;
}

// FUNCTION: BFME2 0x002ABEF1 size=175 name=?canBuild@Player@@QBE_NPBVThingTemplate@@@Z evidence=N:ledger tier=A
Bool Player::canBuild(const ThingTemplate *tmplate) const
{
	if (!tmplate)
		return false;

	if (!allowedToBuild(tmplate))
		return false;

	if (tmplate->getBuildable() == BSTATUS_NO)
		return false;

	if (tmplate->getBuildable() == BSTATUS_IGNORE_PREREQUISITES)
		return true;

	if (tmplate->getBuildable() == BSTATUS_ONLY_BY_AI && m_playerType != PLAYER_COMPUTER)
		return false;

	{
		Bool prereqsOK = true;
		for (Int i = 0; i < tmplate->getPrereqCount(); i++)
		{
			const ProductionPrerequisite *pre = &tmplate->m_prereqInfo[i];
			if (pre->isSatisfied(this) == false)
				prereqsOK = false;
		}

		if (!prereqsOK)
			return false;
	}

	return true;
}

// FUNCTION: BFME2 0x002ABFA0 size=35 name=?rva002ABFA0@Rva002ABFA0@@QAEXPAX@Z evidence=?:placeholder tier=A
void Player::allowToBuild(const ThingTemplate *tmpl)
{
	m_forbiddenTemplateIDs.remove(tmpl->getTemplateID());
}

