// FUNCTION: BFME2 0x002AC5AC size=94 name=?doFindCommandCenter@@YAHPAVObject@@PAX@Z evidence=N:ledger tier=A
// iterateObjects callback for findNaturalCommandCenter: userData is { Player *, Object *found }.
Int doFindCommandCenter(Object *candidate, void *userData)
{
	if (!candidate)
		return 1;
	void **search = (void **)userData;
	if (search[1] == NULL && candidate->getTemplate()->isKindOf(KINDOF_COMMANDCENTER)
		&& candidate->getTemplate()->m_side == ((Player *)search[0])->getSide()
		&& !candidate->testStatus(OBJECT_STATUS_UNDER_CONSTRUCTION) && !candidate->testStatus(OBJECT_STATUS_SOLD))
	{
		search[1] = candidate;
		return 0;
	}
	return 1;
}

// FUNCTION: BFME2 0x002AC60A size=31 name=?findNaturalCommandCenter@Player@@QAEPAVObject@@XZ evidence=N:ledger tier=A
Object *Player::findNaturalCommandCenter()
{
	void *search[2];
	search[1] = NULL;
	search[0] = this;
	iterateObjects(doFindCommandCenter, search);
	return (Object *)search[1];
}

