// FUNCTION: BFME2 0x002AC92B size=148 name=?removeBattlePlanBonusesForObject@Player@@QBEXPAVObject@@@Z evidence=N:ledger tier=A
void Player::removeBattlePlanBonusesForObject(Object *obj) const
{
	// Copy the bonuses and invert them (Zero Hour's text; its ALL_PLANS is 1000000).
	BattlePlanBonuses *bonus = new BattlePlanBonuses;
	*bonus = *m_battlePlanBonuses;
	bonus->m_armorDamageFactor = 1.0f / (bonus->m_armorDamageFactor > 0.01f ? bonus->m_armorDamageFactor : 0.01f);
	bonus->m_sightRangeFactor = 1.0f / (bonus->m_sightRangeFactor > 0.01f ? bonus->m_sightRangeFactor : 0.01f);
	bonus->m_bombardmentActive = -1000000;
	bonus->m_searchActive = -1000000;
	bonus->m_holdLineActive = -1000000;

	localApplyBattlePlanBonusesToObject(obj, bonus);

	delete bonus;
}

