// FUNCTION: BFME2 0x002ACA86 size=117 name=?processCreateTeamGameMessage@Player@@QAEXHPBVGameMessage@@@Z evidence=N:ledger tier=A
void Player::processCreateTeamGameMessage(int hotkeyNum, GameMessage const *msg)
{
	// GameMessage arguments are the object ID's of the objects that are to be in this team.

	if ((hotkeyNum < 0) || (hotkeyNum >= 10))
		return;

	m_squads[hotkeyNum]->clearSquad();

	UnsignedByte numArgs = msg->getArgumentCount();
	for (UnsignedByte i = 0; i < numArgs; ++i)
	{
		ObjectID objID = msg->getArgument(i)->objectID;
		Object *obj = TheGameLogic->findObjectByID(objID);
		if (obj != NULL)
		{
			// first, remove it from any other hotkey squads it is in.
			removeObjectFromHotkeySquad(obj);
			m_squads[hotkeyNum]->addObject(obj);
		}
	}
}

// FUNCTION: BFME2 0x002ACAFB size=173 name=?processSelectTeamGameMessage@Player@@QAEXHPAVGameMessage@@@Z evidence=N:ledger tier=A
void Player::processSelectTeamGameMessage(Int hotkeyNum, GameMessage *msg)
{
	if ((hotkeyNum < 0) || (hotkeyNum >= 10))
		return;

	if (m_squads[hotkeyNum] == NULL)
		return;

	if (m_currentSelection == NULL)
		m_currentSelection = new Squad;

	m_currentSelection->clearSquad();

	const _STL::vector<Object *> &objectList = m_squads[hotkeyNum]->getLiveObjects(true);
	Int numObjs = objectList.size();
	Bool createNewSelection = TRUE;
	for (Int i = 0; i < numObjs; ++i)
	{
		TheGameLogic->selectObject(objectList[i], createNewSelection, getPlayerMask(), FALSE);
		createNewSelection = FALSE;
	}
}

// FUNCTION: BFME2 0x002ACBA8 size=171 name=?processAddTeamGameMessage@Player@@QAEXHPAVGameMessage@@@Z evidence=N:ledger tier=A
void Player::processAddTeamGameMessage(Int hotkeyNum, GameMessage *msg)
{
	if ((hotkeyNum < 0) || (hotkeyNum >= 10))
		return;

	if (m_squads[hotkeyNum] == NULL)
		return;

	if (m_currentSelection == NULL)
		m_currentSelection = new Squad;

	const _STL::vector<Object *> &objectList = m_squads[hotkeyNum]->getLiveObjects(true);
	Int numObjs = objectList.size();
	for (Int i = 0; i < numObjs; ++i)
	{
		Object *obj = objectList[i];
		m_currentSelection->addObject(obj);
		TheGameLogic->selectObject(obj, FALSE, getPlayerMask(), FALSE);
	}
}

