// FUNCTION: BFME2 0x002AD0C6 size=88 name=?getRelationship@Player@@QBE?AW4Relationship@@PBVTeam@@@Z evidence=N:ledger tier=A
Relationship Player::getRelationship(const Team *that) const
{
	if (that != NULL)
	{
		// an override for that particular team
		if (!m_teamRelations->m_map.empty())
		{
			TeamRelationHash::const_iterator it = m_teamRelations->m_map.find(that->getID());
			if (it != m_teamRelations->m_map.end())
				return (*it).second;
		}
		// otherwise the relationship to that team's player
		return getRelationship(that->getControllingPlayer());
	}
	return NEUTRAL;
}

