// FUNCTION: BFME2 0x002ADCE1 size=80 name=?rva002ADCE1@Rva000427195@@QAEXABUVideoPair@@@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002ADD31 size=68 name=?rva002ADD31@Rva002ADD31@@QAEPAXPBX@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002ADD75 size=61 name=?Rva002ADD75Equal@@YAHPBUAsciiRange002ADD75@@0@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002ADDD9 size=124 name=?rva002ADDD9@Rva002AE71D@@QAEXPAVXfer@@@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002ADE71 size=77 name=?rva002ADE71@PlayerRelationMap@@QAEPAV1@PBV1@@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002ADEBE size=222 name=?xfer@PlayerRelationMap@@MAEXPAVXfer@@@Z evidence=N:ledger tier=A
void PlayerRelationMap::xfer(Xfer *xfer)
{
	if (xfer->IsLightCRC())
		return;

	Xfer::Version ver(1, 1);
	*xfer == ver;

	PlayerRelationHash::iterator it;
	UnsignedShort relationCount = (UnsignedShort)m_map.size();
	*xfer == relationCount;

	Int playerIndex;
	Int relationship;
	if (xfer->IsStoring())
	{
		for (it = m_map.begin(); it != m_map.end(); ++it)
		{
			playerIndex = (*it).first;
			*xfer == playerIndex;
			relationship = (*it).second;
			XferRelationship(xfer, &relationship);
		}
	}
	else
	{
		for (UnsignedShort i = 0; i < relationCount; ++i)
		{
			*xfer == playerIndex;
			XferRelationship(xfer, &relationship);
			m_map[playerIndex] = (Relationship)relationship;
		}
	}
}

