// FUNCTION: BFME2 0x002AE71D size=78 name=?rva002AE71D@Rva002AE71D@@QAEXPAVXfer@@@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002AE770 size=351 name=?update@Player@@QAEXXZ evidence=N:ledger tier=A

// FUNCTION: BFME2 0x002AE8CF size=97 name=?rva002AE8CF@Player@@QAEXPBVAsciiString@@MH@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002AE930 size=91 name=?rva002AE930@Player@@QAEXPBVAsciiString@@@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002AE98B size=45 name=?rva002AE98B@Rva002AE98B@@QAEMPBVAsciiString@@@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x002AE9B8 size=231 name=?setUnitsShouldHunt@Player@@QAEX_NW4CommandSourceType@@@Z evidence=N:ledger tier=A
void Player::setUnitsShouldHunt(Bool unitsShouldHunt, CommandSourceType source)
{
	m_unitsShouldHunt = unitsShouldHunt;

	for (ProtoList::iterator it = m_playerTeamPrototypes.begin(); it != m_playerTeamPrototypes.end(); ++it)
	{
		for (DLINK_ITERATOR<Team> iter = (*it)->iterate_TeamInstanceList(); !iter.done(); iter.advance())
		{
			Team *team = iter.cur();
			if (!team)
				continue;
			Object *obj;
			for (DLINK_ITERATOR<Object> iterObj = team->iterate_TeamMemberList(); (obj = iterObj.cur()) != NULL; iterObj.advance())
			{
				KindOfMaskType disqualifyingKindofs;
				disqualifyingKindofs.set(KINDOF_DOZER);
				disqualifyingKindofs.set(KINDOF_HARVESTER);
				disqualifyingKindofs.set(KINDOF_IGNORES_SELECT_ALL);

				if (obj->isAnyKindOf(disqualifyingKindofs))
					continue;	// Harvesters, dozers etc.
				if (obj->testStatus(OBJECT_STATUS_HORDE_MEMBER))
					continue;

				obj->leaveGroup();
				AIUpdateInterface *ai = obj->getAIUpdateInterface();
				if (ai)
				{
					if (unitsShouldHunt)
						ai->aiHunt(source);
					else
						ai->aiIdle(source);
				}
			}
		}
	}
}

// FUNCTION: BFME2 0x002AEA9F size=1032 name=?transferAssetsFromThat@Player@@QAEXPAV1@_N@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x002AEEA7 size=400 name=?garrisonAllUnits@Player@@QAEXW4CommandSourceType@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x002AF037 size=142 name=?ungarrisonAllUnits@Player@@QAEXW4CommandSourceType@@@Z evidence=N:ledger tier=A
void Player::ungarrisonAllUnits(CommandSourceType source)
{
	for (ProtoList::iterator it = m_playerTeamPrototypes.begin(); it != m_playerTeamPrototypes.end(); ++it)
	{
		for (DLINK_ITERATOR<Team> iter = (*it)->iterate_TeamInstanceList(); !iter.done(); iter.advance())
		{
			Team *team = iter.cur();
			if (!team)
				continue;
			for (DLINK_ITERATOR<Object> iterObj = team->iterate_TeamMemberList(); !iterObj.done(); iterObj.advance())
			{
				Object *obj = iterObj.cur();
				if (!obj)
					continue;
				AIUpdateInterface *ai = obj->getAIUpdateInterface();
				if (!ai)
					continue;
				// Evacuate what is in a building; transports are left alone.
				if (obj->getTemplate()->isKindOf(KINDOF_STRUCTURE))
					ai->aiEvacuate(FALSE, source);
			}
		}
	}
}

// FUNCTION: BFME2 0x002AF0C5 size=214 name=?setUnitsShouldIdleOrResume@Player@@QAEX_N@Z evidence=N:ledger tier=A
void Player::setUnitsShouldIdleOrResume(Bool idle)
{
	for (ProtoList::iterator it = m_playerTeamPrototypes.begin(); it != m_playerTeamPrototypes.end(); ++it)
	{
		for (DLINK_ITERATOR<Team> iter = (*it)->iterate_TeamInstanceList(); !iter.done(); iter.advance())
		{
			Team *team = iter.cur();
			if (!team)
				continue;
			for (DLINK_ITERATOR<Object> iterObj = team->iterate_TeamMemberList(); !iterObj.done(); iterObj.advance())
			{
				Object *obj = iterObj.cur();
				if (!obj)
					continue;
				if (obj->getTemplate()->isKindOf(KINDOF_STRUCTURE))
					continue;
				AIUpdateInterface *ai = obj->getAIUpdateInterface();
				if (!ai)
					continue;
				if (idle)
				{
					// force it to move to its position to make it stop.
					ai->aiMoveToPosition(obj->getPosition(), CMD_FROM_SCRIPT);
				}
				else
				{
					if (ai->isIdle())
					{
						SupplyTruckAIInterface *supplyTruckAI = ai->getSupplyTruckAIInterface();
						if (supplyTruckAI)
							supplyTruckAI->setForceWantingState(true);
					}
				}
			}
		}
	}
}

// FUNCTION: BFME2 0x002AF19B size=81 name=?initPlayerUpgrades@Player@@QAEXXZ evidence=N:ledger tier=A
void Player::initPlayerUpgrades()
{
	const PlayerTemplate *pt = m_playerTemplate;
	if (pt)
	{
		Int count = pt->m_initialUpgrades.size();
		for (Int i = 0; i < count; ++i)
		{
			const UpgradeTemplate *upgradeTemplate = TheUpgradeCenter->findUpgrade(pt->m_initialUpgrades[i]);
			if (upgradeTemplate)
				addUpgrade(upgradeTemplate, UPGRADE_STATUS_COMPLETE, 0);
		}
	}
}

